    border: 1px solid #3a2410; padding: 9px 20px; font-size: 15px; font-weight: 600;
    border-radius: 10px; cursor: pointer; box-shadow: 0 3px 8px rgba(0,0,0,.4);
  }
  button:hover { filter: brightness(1.15); }
